import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  tasks: defineTable({
    text: v.string(),
    isCompleted: v.boolean(),
    runId: v.string(),
  }).index("by_runId", ["runId"]),
});

import { mutation, query } from "convex/server";
import { v } from "convex/values";

export const listTasks = query({
  args: { runId: v.string() },
  handler: async (ctx, { runId }) => {
    return ctx.db
      .query("tasks")
      .withIndex("by_runId", (q) => q.eq("runId", runId))
      .order("desc")
      .collect();
  },
});

export const addTask = mutation({
  args: { text: v.string(), runId: v.string() },
  handler: async (ctx, { text, runId }) => {
    return ctx.db.insert("tasks", {
      text,
      runId,
      isCompleted: false,
    });
  },
});

export const toggleTask = mutation({
  args: { id: v.id("tasks"), runId: v.string() },
  handler: async (ctx, { id, runId }) => {
    const task = await ctx.db.get(id);
    if (!task || task.runId !== runId) {
      throw new Error("Task not found for this run.");
    }

    await ctx.db.patch(id, { isCompleted: !task.isCompleted });
    return null;
  },
});

export const deleteTask = mutation({
  args: { id: v.id("tasks"), runId: v.string() },
  handler: async (ctx, { id, runId }) => {
    const task = await ctx.db.get(id);
    if (!task || task.runId !== runId) {
      throw new Error("Task not found for this run.");
    }

    await ctx.db.delete(id);
    return null;
  },
});

import { makeFunctionReference, type Id } from "convex/server";

export type Task = {
  _id: Id<"tasks">;
  text: string;
  isCompleted: boolean;
  runId: string;
};

export const listTasks = makeFunctionReference<
  "query",
  { runId: string },
  Task[]
>("tasks:listTasks");

export const addTask = makeFunctionReference<
  "mutation",
  { text: string; runId: string },
  Id<"tasks">
>("tasks:addTask");

export const toggleTask = makeFunctionReference<
  "mutation",
  { id: Id<"tasks">; runId: string },
  null
>("tasks:toggleTask");

export const deleteTask = makeFunctionReference<
  "mutation",
  { id: Id<"tasks">; runId: string },
  null
>("tasks:deleteTask");

"use client";

import { ConvexProvider, ConvexReactClient } from "convex/react";
import { ReactNode } from "react";

const convexUrl = process.env.NEXT_PUBLIC_CONVEX_URL;

if (!convexUrl) {
  throw new Error("NEXT_PUBLIC_CONVEX_URL is not set.");
}

const convexClient = new ConvexReactClient(convexUrl);

export default function ConvexClientProvider({
  children,
}: {
  children: ReactNode;
}) {
  return <ConvexProvider client={convexClient}>{children}</ConvexProvider>;
}

